"""AABB collision detection with minimal-penetration resolution.

Coordinates are mathematical (y increases upward). A box occupies
[x, x + w] x [y, y + h].
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass
class Aabb:
    x: float
    y: float
    w: float
    h: float

    @property
    def maxx(self) -> float:
        return self.x + self.w

    @property
    def maxy(self) -> float:
        return self.y + self.h

    def overlaps(self, other: "Aabb") -> bool:
        """Strict overlap test; edge-touching counts as no overlap."""
        return (
            self.x < other.maxx
            and other.x < self.maxx
            and self.y < other.maxy
            and other.y < self.maxy
        )


def resolve(a: Aabb, b: Aabb) -> tuple[float, float]:
    """Push box ``a`` out of static box ``b`` along the axis of least penetration.

    Returns the correction vector to apply to ``a``. If the boxes do not
    overlap (including mere edge contact), returns ``(0.0, 0.0)``. Ties
    between axes are broken toward x.
    """
    if not a.overlaps(b):
        return (0.0, 0.0)

    # Candidate escape depths and their signed corrections.
    px_left = a.maxx - b.x        # move a left  -> correction (-px_left, 0)
    px_right = b.maxx - a.x       # move a right -> correction (+px_right, 0)
    py_down = a.maxy - b.y        # move a down  -> correction (0, -py_down)
    py_up = b.maxy - a.y          # move a up    -> correction (0, +py_up)

    cx = -px_left if px_left <= px_right else px_right
    cy = -py_down if py_down <= py_up else py_up

    if abs(cx) <= abs(cy):
        return (float(cx), 0.0)
    return (0.0, float(cy))

